// Este node transforma 1 item con múltiples binarios
// en N items con 1 binario cada uno

const output = [];

for (const item of items) {
  if (!item.binary) continue;

  for (const key of Object.keys(item.binary)) {
    output.push({
      json: {
        originalKey: key, // opcional, útil para debug
      },
      binary: {
        data: item.binary[key], // 🔑 CLAVE: mantener referencia intacta
      },
    });
  }
}

return output;

// Búsqueda semántica (vectorial) — evita ambigüedades de keywords
const query = ($input.first()?.json?.query || $input.first()?.json?.input || '').toString().trim();

if (!query) return 'No se encontraron resultados para esa búsqueda.';

const http = require('http');

const httpPost = (hostname, port, path, body) => new Promise((resolve, reject) => {
  const bodyStr = JSON.stringify(body);
  const req = http.request({
    hostname, port, path,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(bodyStr) }
  }, (res) => {
    let d = '';
    res.on('data', c => d += c);
    res.on('end', () => { try { resolve(JSON.parse(d)); } catch(e) { reject(e); } });
  });
  req.on('error', reject);
  req.write(bodyStr);
  req.end();
});

// 1. Embed de la query
const embedRes = await httpPost('10.0.0.10', 11434, '/api/embeddings', {
  model: 'mxbai-embed-large:latest',
  prompt: query
});

const vector = embedRes?.embedding;
if (!vector) return 'Error al generar embedding de la consulta.';

// 2. Búsqueda vectorial en Qdrant
const searchRes = await httpPost('qdrant', 6333, '/collections/secretaria/points/search', {
  vector,
  limit: 6,
  with_payload: true
});

const points = searchRes?.result || [];

if (points.length === 0) {
  return 'No se encontró información sobre: ' + query;
}

return points
  .map(p => p.payload?.content || '')
  .filter(Boolean)
  .join('\n\n---\n\n');
